def rakuten_amt(month):
    y,mo=map(int,month.split('/'))
    if y==2026:
        if mo==2 or mo==3: return 72513
        if mo==4: return 56109
        if mo==5: return 49295
        if 6<=mo<=10: return 34723
        if mo in (11,12): return 4138
    return 0

def mufg_amt(month):
    y,mo=map(int,month.split('/'))
    if y==2026:
        if 2<=mo<=10: return 111421
        if mo in (11,12): return 100818
    if y==2027:
        if mo==1: return 100818
        if 2<=mo<=10: return 52360
    return 0

def smbc_amt(month):
    y,mo=map(int,month.split('/'))
    if (y==2026 and mo>=2) or (y==2027 and mo<=10):
        return 16543
    return 0

def d_amt(month):
    y,mo=map(int,month.split('/'))
    if (y==2026 and mo>=2) or (y==2027 and mo<=6):
        return 24100
    return 0

def life_amt(month):
    y,mo=map(int,month.split('/'))
    if (y==2026 and mo>=2) or (y==2027 and mo<=10):
        return 12100
    return 0

totals=OrderedDict()
for mon in months:
