from datetime import date
def ym_range(start_ym, end_ym):
    sy, sm = map(int,start_ym.split('/'))
    ey, em = map(int,end_ym.split('/'))
    y,m=sy,sm
    res=[]
    while (y,m) <= (ey,em):
        res.append(f"{y}/{m:02d}")
        m+=1
        if m==13:
            y+=1; m=1
    return res

